macro_rules! EncodeError {
    () => {
        # [doc = " Errors that can be encountered by encoding a type"] # [non_exhaustive] # [derive (Debug)] pub enum EncodeError { # [doc = " The writer ran out of storage."] UnexpectedEnd , # [doc = " The `RefCell<T>` is already borrowed"] RefCellAlreadyBorrowed { # [doc = " The inner borrow error"] inner : core :: cell :: BorrowError , # [doc = " the type name of the RefCell being encoded that is currently borrowed."] type_name : & 'static str , } , # [doc = " An uncommon error occurred, see the inner text for more information"] Other (& 'static str) , # [doc = " An uncommon error occurred, see the inner text for more information"] # [cfg (feature = "alloc")] OtherString (alloc :: string :: String) , # [doc = " A `std::path::Path` was being encoded but did not contain a valid `&str` representation"] # [cfg (feature = "std")] InvalidPathCharacters , # [doc = " The targeted writer encountered an `std::io::Error`"] # [cfg (feature = "std")] Io { # [doc = " The encountered error"] inner : std :: io :: Error , # [doc = " The amount of bytes that were written before the error occurred"] index : usize , } , # [doc = " The encoder tried to encode a `Mutex` or `RwLock`, but the locking failed"] # [cfg (feature = "std")] LockFailed { # [doc = " The type name of the mutex for debugging purposes"] type_name : & 'static str , } , # [doc = " The encoder tried to encode a `SystemTime`, but it was before `SystemTime::UNIX_EPOCH`"] # [cfg (feature = "std")] InvalidSystemTime { # [doc = " The error that was thrown by the SystemTime"] inner : std :: time :: SystemTimeError , # [doc = " The SystemTime that caused the error"] time : std :: boxed :: Box < std :: time :: SystemTime > , } , # [cfg (feature = "serde")] # [doc = " A serde-specific error that occurred while decoding."] Serde (crate :: features :: serde :: EncodeError) , }
    };
}

EncodeError!();